<!-- Botón de calificar -->
<div style="text-align: center; margin: 1.5rem 0;"><button id="btnCalificar" style="background: #f5a623; color: #1e2a36; padding: 0.7rem 2rem; border-radius: 40px; font-weight: bold; border: none; cursor: pointer; font-size: 1rem;">📊 Calificar</button></div>
<!-- Resultado final -->
<div id="resultadoFinal" style="background: #1e3c5c; color: white; border-radius: 24px; padding: 1rem; text-align: center; display: none;">
