</div>
<!-- Script de calificación -->
<script>
        // Respuestas correctas
        const respuestasCorrectas = {
            q1: 'b',
            q2: 'b',
            q3: 'b',
            q4: 'b',
            q5: 'b',
            q6: 'b',
            q7: 'b'
        };

        // Retroalimentación por pregunta
        const feedbackText = {
            q1: '✅ Correcto. "Esforzarse / Perseverar" es el sinónimo formal de "echarle ganas".',
            q1_w: '❌ Incorrecto. La respuesta correcta es b) Esforzarse / Perseverar.',
            q2: '✅ Correcto. La comprensión oral es activa: requiere interpretar, analizar y procesar.',
            q2_w: '❌ Incorrecto. Es falso: la comprensión oral es un proceso activo.',
            q3: '✅ Correcto. La estructura gramatical es lingüística, no paralingüística. Volumen y ritmo sí lo son.',
            q3_w: '❌ Incorrecto. El elemento que NO es paralingüístico es b) La estructura gramatical.',
            q4: '✅ Correcto. Los trabalenguas en voz alta ejercitan la dicción y la agilidad verbal.',
            q4_w: '❌ Incorrecto. La mejor opción es b) Practicar trabalenguas en voz alta.',
            q5: '✅ Correcto. El moderador facilita el debate, controla tiempos y resume.',
            q5_w: '❌ Incorrecto. La función correcta es b) Controlar tiempos, dar la palabra y resumir.',
            q6: '✅ Correcto. La idea principal es que la práctica, retroalimentación y colaboración mejoran la expresión oral.',
            q6_w: '❌ Incorrecto. La respuesta correcta es b).',
            q7: '✅ Correcto. Las muletillas como "este", "o sea" afectan la fluidez y deben evitarse.',
            q7_w: '❌ Incorrecto. El ejemplo de muletilla es b) "Este... o sea... ¿cómo te explico?"'
        };

        function calificar() {
            let puntaje = 0;
            // Mostrar feedback y contar correctas
            for (let i = 1; i <= 7; i++) {
                const name = 'q' + i;
                const radios = document.getElementsByName(name);
                let selectedValue = null;
                for (let r of radios) {
                    if (r.checked) {
                        selectedValue = r.value;
                        break;
                    }
                }
                const fbDiv = document.getElementById('fb' + i);
                if (selectedValue === respuestasCorrectas[name]) {
                    puntaje++;
                    fbDiv.innerHTML = feedbackText[name];
                    fbDiv.style.color = 'green';
                } else {
                    fbDiv.innerHTML = feedbackText[name + '_w'] || feedbackText[name];
                    fbDiv.style.color = 'red';
                }
            }
            // Mostrar resultado final
            const resultadoDiv = document.getElementById('resultadoFinal');
            const puntajeSpan = document.getElementById('puntaje');
            const mensaje = document.getElementById('mensajeFeedback');
            puntajeSpan.textContent = puntaje;
            if (puntaje === 7) {
                mensaje.innerHTML = '🎉 ¡Excelente! Dominas los conceptos de expresión y comprensión oral. Sigue así.';
            } else if (puntaje >= 5) {
                mensaje.innerHTML = '👍 Muy bien. Revisa las retroalimentaciones para seguir mejorando.';
            } else {
                mensaje.innerHTML = '📚 Te sugerimos repasar los módulos de vocabulario y dicción. ¡Tú puedes!';
            }
            resultadoDiv.style.display = 'block';
            // Desplazar suavemente al resultado
            resultadoDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }

        function reiniciarExamen() {
            // Limpiar selecciones y feedbacks
            for (let i = 1; i <= 7; i++) {
                const radios = document.getElementsByName('q' + i);
                radios.forEach(r => r.checked = false);
                const fbDiv = document.getElementById('fb' + i);
                fbDiv.innerHTML = '';
                fbDiv.style.color = '';
            }
            document.getElementById('resultadoFinal').style.display = 'none';
            // Opcional: limpiar también el puntaje mostrado
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }

        document.getElementById('btnCalificar').addEventListener('click', calificar);
        document.getElementById('reiniciar').addEventListener('click', reiniciarExamen);
    </script>
<!-- Botón de finalización (opcional) -->
<div style="text-align: center; margin-top: 1.5rem;"><button style="background: #2c5f8a; color: white; padding: 0.6rem 1.5rem; border-radius: 40px; border: none; cursor: pointer; font-weight: bold;" onclick="alert('¡Has completado EXPRETODOS! Sigue practicando para mejorar tu expresión oral.')">🏁 Finalizar y cerrar</button></div>
</div>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
